const SELL_WD_COLOR="green";
const SELL_SPEED_COLOR="black";

function setStatus(text){const node=$("status");if(node){node.innerHTML=text}}function syncCapitalOverlayToggle(){const node=$("toggleCapitalOverlay");if(node){node.checked=!!state.showCapitalOverlay}}function saveCapitalOverlay(value){state.showCapitalOverlay=!!value;syncCapitalOverlayToggle();try{localStorage.setItem("dashboard_show_capital_overlay",state.showCapitalOverlay?"1":"0")}catch(error){}}
function setupLayout(){const wrap=document.querySelector(".wrap");const panel=document.querySelector(".panel");const drawer=$("settingsDrawer");if(!wrap||!panel||!drawer)return;let shell=wrap.querySelector(".app-shell");if(!shell){shell=document.createElement("div");shell.className="app-shell";wrap.insertBefore(shell,panel)}if(panel.parentElement!==shell){shell.appendChild(panel)}drawer.classList.add("app-drawer");if(drawer.parentElement!==shell){shell.appendChild(drawer)}const titleNode=drawer.querySelector(".drawer-title-wrap .charttitle");if(titleNode){titleNode.className="title";titleNode.textContent="Backtest Dashboard"}const subNode=drawer.querySelector(".drawer-title-wrap .sub");if(subNode){subNode.textContent="总览读取 outcome_stats，详情切换读取 trans.xlsx，原 HTML 仍可随时打开。"}let workspaceCard=document.getElementById("workspaceCard");if(!workspaceCard){workspaceCard=document.createElement("div");workspaceCard.id="workspaceCard";workspaceCard.className="chartbox";workspaceCard.innerHTML='<div class="charttitle">工作区</div><div id="workspaceControls" class="rail-stack"></div>';const drawerBody=drawer.querySelector(".drawer-body");if(drawerBody){drawerBody.insertBefore(workspaceCard,drawerBody.firstChild)}}const workspaceControls=document.getElementById("workspaceControls");if(workspaceControls){for(const id of ["folderName","batchSelect","pickBtn"]){const node=$(id);if(node&&node.parentElement!==workspaceControls){workspaceControls.appendChild(node)}}const tabs=document.querySelector(".tabs");if(tabs&&tabs.parentElement!==workspaceControls){workspaceControls.appendChild(tabs)}}const top=document.querySelector(".top");if(top){top.remove()}const detailShell=document.querySelector("#pageDetail .detail-shell");const priceBox=detailShell?.querySelector(".price-box");const controlsCard=document.querySelector("#pageDetail .controls-card");if(detailShell&&priceBox&&controlsCard&&detailShell.firstElementChild!==controlsCard){detailShell.insertBefore(controlsCard,priceBox)}}
function setTab(name){$("tabOverview").classList.toggle("active",name==="overview");$("tabDetail").classList.toggle("active",name==="detail");$("pageOverview").classList.toggle("active",name==="overview");$("pageDetail").classList.toggle("active",name==="detail")}
function setSettingsCollapsed(collapsed){state.settingsCollapsed=collapsed;$("settingsDrawer").classList.toggle("collapsed",collapsed);$("settingsToggle").textContent=collapsed?"展开":"收起"}
function pathOf(file){return String(file.relative_path||file.webkitRelativePath||"")}
function rel(file){return String(pathOf(file)||file.name).replaceAll("\\","/")}
function inDir(file,dir){const path=rel(file).toLowerCase();const prefix=dir.toLowerCase()+"/";return path.startsWith(prefix)||path.includes("/"+prefix)}
function esc(text){return String(text).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;")}
function keyOf(v){if(v===null||v===undefined||v==="")return"";const n=Number(v);if(Number.isNaN(n))return"";return String(Number(n.toFixed(10))).replace(/\.0+$/,"")}function formatParamDisplay(value){if(value===null||value===undefined||value==="")return"";const n=Number(value);if(Number.isNaN(n))return String(value);if(Number.isInteger(n))return String(n);return n.toFixed(3)}function formatParamTag(tag){return String(tag??"").replace(/-?\d+\.\d+/g,match=>formatParamDisplay(match))}
function selKey(){return [keyOf($("inputBar").value),keyOf($("inputThreshold").value),keyOf($("inputCont").value)].join("|")}
function isSummary(file){return inDir(file,"outcome stats")&&file.name.toLowerCase().endsWith("outcome_stats.xlsx")}
function isTrans(file){return inDir(file,"trans")&&file.name.toLowerCase().endsWith("trans.xlsx")}
function isPerf(file){return inDir(file,"perf")&&file.name.toLowerCase().endsWith("perf.xlsx")}
function isHtml(file){return inDir(file,"html")&&file.name.toLowerCase().endsWith(".html")}
function fileMtime(file){return Number(file.last_modified??file.lastModified??0)}
function shortTick(value){const text=String(value||"");return text.length>16?text.slice(5,16):text}
function axisLabel(value){return String(value??"")}
function sampleIndexTicks(values,count=8){if(!values||!values.length)return{vals:[],labels:[]};if(values.length<=count){return{vals:values.map((_,index)=>index),labels:values.map(shortTick)}}const step=Math.max(1,Math.ceil(values.length/count));const vals=[];const labels=[];for(let index=0;index<values.length;index+=step){vals.push(index);labels.push(shortTick(values[index]))}const lastIndex=values.length-1;if(vals[vals.length-1]!==lastIndex){vals.push(lastIndex);labels.push(shortTick(values[lastIndex]))}return{vals,labels}}
function numericAxis(values){const ticks=sampleIndexTicks(values);return{type:"linear",tickmode:"array",tickvals:ticks.vals,ticktext:ticks.labels,showgrid:false,zeroline:false,rangeslider:{visible:false}}}
function buildIndexMap(values){const map=new Map();for(let index=0;index<(values||[]).length;index+=1){const key=axisLabel(values[index]);if(key&&!map.has(key)){map.set(key,index)}}return map}
function axisPoints(xs,ys,indexMap,keepBreaks=false){const outX=[];const outY=[];const labels=[];for(let index=0;index<(xs||[]).length;index+=1){const label=axisLabel(xs[index]);if(!label){if(keepBreaks){outX.push(null);outY.push(null);labels.push("")}continue}const axisX=indexMap.get(label);if(axisX===undefined){if(keepBreaks){outX.push(null);outY.push(null);labels.push("")}continue}outX.push(axisX);outY.push(ys[index]);labels.push(label)}return{x:outX,y:outY,text:labels}}
function gapShapes(values){const shapes=[];const dayMs=24*60*60*1000;for(let index=1;index<(values||[]).length;index+=1){const leftMs=Date.parse(String(values[index-1]||"").replace(" ","T"));const rightMs=Date.parse(String(values[index]||"").replace(" ","T"));if(!Number.isFinite(leftMs)||!Number.isFinite(rightMs))continue;if(rightMs-leftMs<=dayMs)continue;shapes.push({type:"line",xref:"x",yref:"paper",x0:index-0.5,x1:index-0.5,y0:0,y1:1,line:{color:"rgba(120,120,120,0.3)",width:1,dash:"dash"}})}return shapes}
function gapShapes(values){const shapes=[];const dayMs=24*60*60*1000;for(let index=1;index<(values||[]).length;index+=1){const leftMs=Date.parse(String(values[index-1]||"").replace(" ","T"));const rightMs=Date.parse(String(values[index]||"").replace(" ","T"));if(!Number.isFinite(leftMs)||!Number.isFinite(rightMs))continue;if(rightMs-leftMs<=dayMs)continue;shapes.push({type:"line",xref:"x",yref:"paper",x0:index-0.5,x1:index-0.5,y0:0,y1:1,line:{color:"rgba(120,120,120,0.3)",width:1,dash:"dash"}})}return shapes}
async function upload(url,file){const fd=new FormData();fd.append("file",file,file.name);const res=await fetch(url,{method:"POST",body:fd});const data=await res.json();if(!res.ok)throw new Error(data.error||"请求失败");return data}
async function fetchJson(url){const res=await fetch(url);const data=await res.json();if(!res.ok)throw new Error(data.error||"request failed");return data}
function clearHtmlPreview(message){const frame=$("htmlFrame");const wrap=$("htmlWrap");const empty=$("htmlEmpty");if(frame){frame.removeAttribute("src")}if(wrap){wrap.classList.remove("active")}if(empty){empty.style.display="grid";empty.innerHTML=message}}
function showHtmlPreview(url){const empty=$("htmlEmpty");const wrap=$("htmlWrap");const frame=$("htmlFrame");if(empty){empty.style.display="none"}if(wrap){wrap.classList.add("active")}if(frame){frame.src=url}}
function resetUi(){for(const url of state.htmlUrlCache.values()){URL.revokeObjectURL(url)}state.summary=null;state.activeRecord=null;state.folderLabel="";state.priceCache.clear();state.transCache.clear();state.htmlUrlCache.clear();$("batchSelect").innerHTML='<option value="">请选择回测批次</option>';$("batchSelect").disabled=true;$("overviewChart").style.display="none";$("priceChart").style.display="none";$("capitalChart").style.display="none";$("overviewEmpty").style.display="grid";$("priceEmpty").style.display="grid";$("capitalEmpty").style.display="grid";$("openHtml").disabled=true;$("inputBar").disabled=true;$("inputThreshold").disabled=true;$("inputCont").disabled=true;clearHtmlPreview("选择一个参数后，可在这里预览对应的原 HTML。");$("metaFolder").textContent="-";$("metaBatch").textContent="-";$("metaTag").textContent="-";$("metaCapital").textContent="-";$("metaTrade").textContent="-";$("metaWd").textContent="-";$("metaHigh").textContent="-"}
function configInput(el,meta){const has=meta&&meta.values&&meta.values.length;el.disabled=!has;if(!has){el.value="";el.removeAttribute("min");el.removeAttribute("max");el.removeAttribute("step");return}el.min=meta.values[0];el.max=meta.values[meta.values.length-1];el.step=meta.step??"any"}
function batchFile(files,label,suffix){const arr=files.filter(file=>file.name.toLowerCase().endsWith(suffix)&&file.name.includes(label)).sort((a,b)=>fileMtime(b)-fileMtime(a));return arr[0]||null}
function detailFile(files,label,paramTag,suffix){const arr=files.filter(file=>file.name.toLowerCase().endsWith(suffix)&&file.name.includes(label)&&file.name.includes(paramTag)).sort((a,b)=>fileMtime(b)-fileMtime(a));return arr[0]||null}
function recordByKey(key){return state.summary?.records.find(item=>item.selection_key===key)||null}
function meta(record){$("metaFolder").textContent=state.folderLabel||"-";if(!record){$("metaBatch").textContent="-";$("metaTag").textContent="-";$("metaCapital").textContent="-";$("metaTrade").textContent="-";$("metaWd").textContent="-";$("metaHigh").textContent="-";return}$("metaBatch").textContent=state.summary.batch_label;$("metaTag").textContent=formatParamTag(record.param_tag);$("metaCapital").textContent=record.capital??"-";$("metaTrade").textContent=record.trade_num??"-";$("metaWd").textContent=record.biggest_wd??"-";$("metaHigh").textContent=record.outcome_high??"-"}
function inputsFrom(record){$("inputBar").value=record.open_bar??"";$("inputThreshold").value=record.open_threshold??"";$("inputCont").value=record.open_continous_threshold??""}
function overview(){if(!state.summary||!state.summary.records.length){$("overviewChart").style.display="none";$("overviewEmpty").style.display="grid";return}const sortMode=$("overviewSortMode")?.value||"current";const numOrInf=value=>{const n=Number(value);return Number.isFinite(n)?n:Infinity};const numOrNegInf=value=>{const n=Number(value);return Number.isFinite(n)?n:-Infinity};const baseRows=[...state.summary.records].sort((a,b)=>numOrInf(a.open_bar)-numOrInf(b.open_bar)||numOrInf(a.open_threshold)-numOrInf(b.open_threshold)||numOrInf(a.open_continous_threshold)-numOrInf(b.open_continous_threshold)||String(a.param_tag||"").localeCompare(String(b.param_tag||""))).map((row,index)=>({...row,__currentOrder:index+1}));const rows=sortMode==="capital"?[...baseRows].sort((a,b)=>numOrNegInf(b.capital)-numOrNegInf(a.capital)||a.__currentOrder-b.__currentOrder):sortMode==="drawdown"?[...baseRows].sort((a,b)=>numOrInf(a.biggest_wd)-numOrInf(b.biggest_wd)||a.__currentOrder-b.__currentOrder):baseRows;const groupTicks=[];const separators=[];if(sortMode==="current"){let groupStart=0;for(let i=1;i<=rows.length;i+=1){const sameGroup=i<rows.length&&keyOf(rows[i]?.open_bar)===keyOf(rows[groupStart]?.open_bar);if(sameGroup)continue;const left=groupStart+1;const right=i;groupTicks.push({value:(left+right)/2,label:formatParamDisplay(rows[groupStart]?.open_bar)});if(i<rows.length){separators.push({type:"line",xref:"x",yref:"paper",x0:i+0.5,x1:i+0.5,y0:0,y1:1,line:{color:"rgba(120,120,120,0.1)",width:1}})}groupStart=i}}$("overviewEmpty").style.display="none";$("overviewChart").style.display="block";Plotly.newPlot($("overviewChart"),[{x:rows.map((_,i)=>i+1),y:rows.map(r=>r.capital),mode:"markers",marker:{size:6,color:"#2f6bff"},customdata:rows.map(r=>r.selection_key),text:rows.map((r,index)=>["param_tag: "+esc(r.param_tag),"当前序号: "+(r.__currentOrder??"-"),"收益排序: "+(sortMode==="capital"?index+1:"-"),"回撤排序: "+(sortMode==="drawdown"?index+1:"-"),"open_bar: "+formatParamDisplay(r.open_bar),"open_threshold: "+formatParamDisplay(r.open_threshold),"open_cont: "+formatParamDisplay(r.open_continous_threshold),"capital: "+(r.capital??"-"),"biggest_wd: "+formatMetric3(r.biggest_wd),"trade_num: "+(r.trade_num??"-")].join("<br>")),hovertemplate:"%{text}<extra></extra>",name:"capital"}],{margin:{l:44,r:18,t:16,b:40},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"#fff",xaxis:sortMode==="capital"?{title:"收益排名",showgrid:false,zeroline:false}:sortMode==="drawdown"?{title:"最小回撤排名",showgrid:false,zeroline:false}:{title:"om",showgrid:false,zeroline:false,tickmode:"array",tickvals:groupTicks.map(item=>item.value),ticktext:groupTicks.map(item=>item.label)},yaxis:{title:"capital",showgrid:false,zeroline:false},shapes:separators,showlegend:false},{responsive:true,displayModeBar:false});if($("overviewChart").removeAllListeners){$("overviewChart").removeAllListeners("plotly_click")}$("overviewChart").on("plotly_click",evt=>{const key=evt?.points?.[0]?.customdata;const record=recordByKey(key);if(record)setRecord(record,true)})}
async function ensurePrice(record){if(!record||!state.summary)return null;const cacheKey=record.selection_key||state.summary.batch_label;if(state.priceCache.has(cacheKey))return state.priceCache.get(cacheKey);const file=detailFile(state.perfFiles,state.summary.batch_label,record.param_tag,"perf.xlsx")||batchFile(state.perfFiles,state.summary.batch_label,"perf.xlsx");if(!file){state.priceCache.set(cacheKey,null);return null}setStatus("正在读取 perf.xlsx");const data=file.relative_path?await fetchJson("/api/preset-price?path="+encodeURIComponent(file.relative_path)):await upload("/api/price",file);state.priceCache.set(cacheKey,data);return data}
async function ensureTrans(record){if(!record||!state.summary)return null;if(state.transCache.has(record.selection_key))return state.transCache.get(record.selection_key);const file=detailFile(state.transFiles,state.summary.batch_label,record.param_tag,"trans.xlsx");if(!file){state.transCache.set(record.selection_key,null);return null}setStatus("正在读取 trans.xlsx");const data=file.relative_path?await fetchJson("/api/preset-trans?path="+encodeURIComponent(file.relative_path)):await upload("/api/trans",file);state.transCache.set(record.selection_key,data);return data}
function priceChart(price,trans){if(!price||!price.x.length){$("priceChart").style.display="none";$("priceEmpty").style.display="grid";$("priceEmpty").innerHTML="当前批次缺少可用的 perf.xlsx。";return}$("priceEmpty").style.display="none";$("priceChart").style.display="block";const candleX=price.x.map((_,index)=>index);const priceIndexMap=buildIndexMap(price.x);const shapes=gapShapes(price.x);const perfCapitalPoints=axisPoints(price.capital_x||[],price.capital_y||[],priceIndexMap);const basePrice=Number(price.price_base);const scaleValue=value=>{if(value===null||value===undefined||value==="")return value;const num=Number(value);if(!Number.isFinite(num)||!Number.isFinite(basePrice)||basePrice===0)return num;return num/basePrice*100};const scaleAxisPoints=points=>({x:[...(points?.x||[])],y:(points?.y||[]).map(scaleValue),text:[...(points?.text||[])]});const traces=[{type:"candlestick",x:candleX,open:price.open,high:price.high,low:price.low,close:price.close,text:price.x,name:"price",increasing:{line:{color:CANDLE_UP_EDGE,width:0.8},fillcolor:CANDLE_UP_FILL},decreasing:{line:{color:CANDLE_DOWN_EDGE,width:0.8},fillcolor:CANDLE_DOWN_FILL},hovertemplate:"%{text}<br>open=%{open:.4f}<br>high=%{high:.4f}<br>low=%{low:.4f}<br>close=%{close:.4f}<extra></extra>"}];const capitalPoints=perfCapitalPoints.x.length?perfCapitalPoints:(trans?axisPoints(trans.capital_x,trans.capital_y,priceIndexMap):{x:[],y:[],text:[]});if(state.showCapitalOverlay&&capitalPoints.x.length)traces.unshift({type:"scatter",mode:"lines",x:capitalPoints.x,y:capitalPoints.y,text:capitalPoints.text,line:{color:ACCENT_BLUE,width:1.2},name:"capital",hovertemplate:"%{text}<br>capital=%{y:.4f}<extra></extra>"});if(trans){const tradeLink=scaleAxisPoints(axisPoints(trans.trade_link_x,trans.trade_link_y,priceIndexMap,true));const buyPoints=scaleAxisPoints(axisPoints(trans.buy_points.x,trans.buy_points.y,priceIndexMap));const sellWdPoints=scaleAxisPoints(axisPoints(trans.sell_wd_points.x,trans.sell_wd_points.y,priceIndexMap));const sellSpeedPoints=scaleAxisPoints(axisPoints(trans.sell_speed_points.x,trans.sell_speed_points.y,priceIndexMap));if(tradeLink.x.length)traces.push({type:"scatter",mode:"lines",x:tradeLink.x,y:tradeLink.y,line:{color:ACCENT_BLUE,width:2},hoverinfo:"skip",name:"trade_link"});if(buyPoints.x.length)traces.push({type:"scatter",mode:"markers",x:buyPoints.x,y:buyPoints.y,text:buyPoints.text,marker:{color:"red",size:4},name:"buy",hovertemplate:"buy<br>%{text}<br>base100=%{y:.4f}<extra></extra>"});if(sellWdPoints.x.length)traces.push({type:"scatter",mode:"markers",x:sellWdPoints.x,y:sellWdPoints.y,text:sellWdPoints.text,marker:{color:SELL_WD_COLOR,size:4},name:"sell_wd",hovertemplate:"sell_wd<br>%{text}<br>base100=%{y:.4f}<extra></extra>"});if(sellSpeedPoints.x.length)traces.push({type:"scatter",mode:"markers",x:sellSpeedPoints.x,y:sellSpeedPoints.y,text:sellSpeedPoints.text,marker:{color:SELL_SPEED_COLOR,size:4},name:"sell_speed",hovertemplate:"sell_speed<br>%{text}<br>base100=%{y:.4f}<extra></extra>"})}Plotly.newPlot($("priceChart"),traces,{margin:{l:48,r:18,t:12,b:36},paper_bgcolor:"rgba(0,0,0,0)",plot_bgcolor:"#fff",xaxis:numericAxis(price.x),yaxis:{title:"price (base=100)",gridcolor:"#e8eef8",zeroline:false},legend:{orientation:"h",yanchor:"bottom",y:1.02,xanchor:"left",x:0},shapes:shapes},{responsive:true,displayModeBar:false})}
function capitalChart(trans){const card=$("capitalChart")?.closest(".chartbox")||$("capitalEmpty")?.closest(".chartbox");if(card){card.style.display="none"}}
function htmlFileFor(record){if(!record||!state.summary)return null;return detailFile(state.htmlFiles,state.summary.batch_label,record.param_tag,".html")}
function htmlUrlFor(record){const file=htmlFileFor(record);if(!file)return"";if(file.relative_path){return"/api/preset-html?path="+encodeURIComponent(file.relative_path)}let url=state.htmlUrlCache.get(record.selection_key);if(!url){url=URL.createObjectURL(file);state.htmlUrlCache.set(record.selection_key,url)}return url}
function htmlEnabled(record){$("openHtml").disabled=!htmlFileFor(record)}
async function setRecord(record,switchTab){state.activeRecord=record;inputsFrom(record);meta(record);htmlEnabled(record);clearHtmlPreview("选择一个参数后，可在这里预览对应的原 HTML。");if(switchTab)setTab("detail");try{const [price,trans]=await Promise.all([ensurePrice(record),ensureTrans(record)]);priceChart(price,trans);capitalChart(trans);setStatus("详情已同步")}catch(error){$("priceChart").style.display="none";$("capitalChart").style.display="none";$("priceEmpty").style.display="grid";$("capitalEmpty").style.display="grid";$("priceEmpty").innerHTML="详情载入失败：<br>"+esc(error.message);$("capitalEmpty").innerHTML="详情载入失败：<br>"+esc(error.message);setStatus("详情载入失败")}}
async function loadSummary(file){setStatus("正在读取 outcome_stats");state.summary=file.relative_path?await fetchJson("/api/preset-summary?path="+encodeURIComponent(file.relative_path)):await upload("/api/summary",file);configInput($("inputBar"),state.summary.controls.open_bar);configInput($("inputThreshold"),state.summary.controls.open_threshold);configInput($("inputCont"),state.summary.controls.open_continous_threshold);overview();const record=recordByKey(state.summary.default_key);if(record)await setRecord(record,false);setStatus("批次已载入")}
function folderChanged(files,folderLabel){resetUi();state.files=[...files];state.summaryFiles=state.files.filter(isSummary);state.transFiles=state.files.filter(isTrans);state.perfFiles=state.files.filter(isPerf);state.htmlFiles=state.files.filter(isHtml);if(!state.files.length){$("folderName").textContent="尚未选择结果大文件夹";setStatus("等待目录");return}state.folderLabel=folderLabel||(rel(state.files[0]).split("/")[0]||"已选择目录");$("folderName").textContent=state.folderLabel;$("metaFolder").textContent=state.folderLabel;const select=$("batchSelect");select.innerHTML='<option value="">请选择回测批次</option>';for(const file of [...state.summaryFiles].sort((a,b)=>fileMtime(b)-fileMtime(a))){const opt=document.createElement("option");opt.value=pathOf(file)||file.name;opt.textContent=file.name.replace(/\.xlsx$/i,"");select.appendChild(opt)}select.disabled=!state.summaryFiles.length;if(!state.summaryFiles.length){setStatus("缺少 outcome_stats");$("overviewEmpty").innerHTML="当前目录里没有 outcome_stats.xlsx。<br>请使用更新后的回测程序重新输出 outcome stats 汇总文件。";return}setStatus("目录已载入");$("overviewEmpty").innerHTML="请选择一个回测批次。"}

$("pickBtn").addEventListener("click",()=>{$("folderInput").click()});
$("folderInput").addEventListener("change",evt=>folderChanged(evt.target.files));
$("batchSelect").addEventListener("change",async()=>{const file=state.summaryFiles.find(item=>(pathOf(item)||item.name)===$("batchSelect").value);if(!file)return;try{await loadSummary(file)}catch(error){$("overviewChart").style.display="none";$("overviewEmpty").style.display="grid";$("overviewEmpty").innerHTML="汇总文件读取失败：<br>"+esc(error.message);setStatus("批次读取失败")}});
$("tabOverview").addEventListener("click",()=>setTab("overview"));
$("tabDetail").addEventListener("click",()=>setTab("detail"));
$("settingsToggle").addEventListener("click",()=>setSettingsCollapsed(!state.settingsCollapsed));
$("inputBar").addEventListener("change",async()=>{const record=recordByKey(selKey());if(record)await setRecord(record,false);else{state.activeRecord=null;meta(null);htmlEnabled(null);$("priceChart").style.display="none";$("capitalChart").style.display="none";$("priceEmpty").style.display="grid";$("capitalEmpty").style.display="grid";$("priceEmpty").innerHTML="当前三元参数组合没有对应结果。";$("capitalEmpty").innerHTML="当前三元参数组合没有对应 trans.xlsx。";clearHtmlPreview("当前三元参数组合没有对应的原 HTML。");setStatus("该参数组合没有结果")}});
$("inputThreshold").addEventListener("change",async()=>{$("inputBar").dispatchEvent(new Event("change"))});
