function ensureParamUi(el){if(!el)return null;if(el._paramUi)return el._paramUi;const host=el.parentElement;if(!host)return null;host.classList.add("param-block");const shell=document.createElement("div");shell.className="param-host";const select=document.createElement("select");select.className="param-select";select.disabled=true;const stepper=document.createElement("div");stepper.className="param-stepper";const up=document.createElement("button");up.type="button";up.className="step-btn";up.textContent="▲";up.title="增大";const down=document.createElement("button");down.type="button";down.className="step-btn";down.textContent="▼";down.title="减小";stepper.appendChild(up);stepper.appendChild(down);shell.appendChild(select);shell.appendChild(stepper);host.insertBefore(shell,el);el.type="hidden";el.classList.add("num-hidden");el.setAttribute("aria-hidden","true");const ui={select,up,down};select.addEventListener("change",()=>{if(select.disabled)return;applyParamValue(el,select.value,true)});up.addEventListener("click",()=>stepParam(el,1));down.addEventListener("click",()=>stepParam(el,-1));el._paramUi=ui;return ui}
